#!/usr/bin/env bash
# Question 5: Service ${Q5_APP} unreachable. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q5_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q5_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q5_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl apply -f - <<EOF
apiVersion: apps/v1
kind: Deployment
metadata:
  name: ${Q5_APP}
  namespace: ${Q5_NS}
spec:
  replicas: 0
  selector:
    matchLabels: { app: ${Q5_APP} }
  template:
    metadata:
      labels: { app: ${Q5_APP} }
    spec:
      containers:
        - name: web
          image: nginx:1.27-alpine
          ports: [{ name: http, containerPort: 80 }]
          readinessProbe:
            httpGet: { path: /, port: http }
            periodSeconds: 5
---
apiVersion: v1
kind: Service
metadata:
  name: ${Q5_APP}
  namespace: ${Q5_NS}
spec:
  selector: { app: ${Q5_APP} }
  ports: [{ port: 80, targetPort: http }]
---
apiVersion: v1
kind: Pod
metadata:
  name: client
  namespace: ${Q5_NS}
spec:
  containers:
    - name: shell
      image: busybox:1.36
      command: ["sleep", "infinity"]
EOF
if ! kubectl -n "${Q5_NS}" wait --for=condition=Ready pod/client --timeout=180s; then
  kubectl -n "${Q5_NS}" describe pod/client >&2 || true
  exit 1
fi

case "${Q5_FAULT}" in
  egress-network-policy)
    kubectl -n "${Q5_NS}" apply -f - <<< '{"apiVersion":"networking.k8s.io/v1","kind":"NetworkPolicy","metadata":{"name":"deny-egress"},"spec":{"podSelector":{},"policyTypes":["Egress"]}}'
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac

kubectl -n "${Q5_NS}" scale "deployment/${Q5_APP}" --replicas=2
# The question only makes sense if the client really is cut off.
for _ in $(seq 1 30); do
  kubectl -n "${Q5_NS}" exec client -- wget -qO- -T 3 "http://${Q5_APP}" 2>/dev/null | grep -q nginx || exit 0
  sleep 2
done
echo "the client can still reach the service" >&2
exit 1
